#Requires -Version 7.6
param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$experimentRoot = $PSScriptRoot
$sourceSha = (git -C $RepositoryRoot rev-parse 'HEAD:src/Grace.Types/DirectoryVersion.Types.fs').Trim()
$scope = '11111111-1111-1111-1111-111111111111'

# Build current contracts into the disposable directory, without borrowing another worktree's assemblies.
$buildArguments = @('build', "$RepositoryRoot/src/Grace.Types/Grace.Types.fsproj", '--configuration', 'Release',
    '--artifacts-path', "$experimentRoot/build", '-p:CopyLocalLockFileAssemblies=true', '--nologo', '-v', 'quiet')
& dotnet @buildArguments 2>&1 | Tee-Object -FilePath "$experimentRoot/build.log"
if ($LASTEXITCODE -ne 0) { throw 'Source build failed.' }
$binaryRoot = "$experimentRoot/build/bin/Grace.Types/release"
$references = @('#I "' + $binaryRoot.Replace('\', '/') + '"')
$references += Get-ChildItem -LiteralPath $binaryRoot -Filter '*.dll' |
    Where-Object Name -NotIn @('FSharp.Core.dll', 'Grace.Types.dll') |
    ForEach-Object { '#r "' + $_.Name + '"' }
$references += '#r "Grace.Types.dll"'
# Preserve the exact source of the whole-file key functions, stopping before unrelated CAS helpers.
$keySource = Get-Content -LiteralPath "$RepositoryRoot/src/Grace.Shared/StorageKeys.Shared.fs" -Raw
$end = $keySource.IndexOf('    /// Builds the legacy SHA-only')
if ($end -lt 0) { throw 'Storage key extraction boundary changed.' }
[IO.File]::WriteAllText("$experimentRoot/StorageKeys.extract.fs", $keySource.Substring(0, $end))
$references += '#load "StorageKeys.extract.fs"'
$references += '#load "SourceSeam.fsx"'
$references | Set-Content -LiteralPath "$experimentRoot/Load.fsx"
& dotnet fsi "$experimentRoot/Load.fsx" 2>&1 | Tee-Object -FilePath "$experimentRoot/source-seam.log"
if ($LASTEXITCODE -ne 0) { throw 'Source seam failed.' }
$rows = @(Get-Content -LiteralPath "$experimentRoot/rows.json" -Raw | ConvertFrom-Json)
$runRoot = New-Item -ItemType Directory -Path (Join-Path $experimentRoot ('capture-' + [guid]::NewGuid().ToString('N')))
$results = [Collections.Generic.List[object]]::new()

# Persists one deterministic fixture page. A null continuation means the bounded enumeration is exhausted.
function Write-Page([string]$Path, [object[]]$Rows, $Next) {
    @{ Rows = @($Rows); Next = $Next } | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $Path
}

# Reads finite file pages; errors and bounds never return a quantity. No partial accumulator survives a retry.
function Read-Capture([string]$Start, [int]$MaxPages = 4, [int]$MaxRows = 20, [string]$StopAt = '', [scriptblock]$AfterPage = {}) {
    $values = [Collections.Generic.Dictionary[string,long]]::new([StringComparer]::Ordinal)
    $pages = 0
    $rowCount = 0
    $next = $Start
    try {
        while ($null -ne $next) {
            if ($pages -ge $MaxPages) { throw 'page-bound' }
            if ($StopAt -eq "before-page-$pages") { throw 'interrupted' }
            $page = Get-Content -LiteralPath $next -Raw | ConvertFrom-Json
            $pages++
            foreach ($row in $page.Rows) {
                $rowCount++
                if ($rowCount -gt $MaxRows) { throw 'row-bound' }
                if ($row.Scope -cne $scope) { throw 'scope-mismatch' }
                if ([string]::IsNullOrWhiteSpace($row.Key)) { throw 'missing-identity' }
                if ($row.Bytes -isnot [long] -and $row.Bytes -isnot [int] -and $row.Bytes -isnot [bigint]) { throw 'invalid-size' }
                if ($row.Bytes -lt 0 -or $row.Bytes -gt [long]::MaxValue) { throw 'invalid-size' }
                if ($values.ContainsKey($row.Key) -and $values[$row.Key] -ne $row.Bytes) { throw 'conflicting-size' }
                $values[$row.Key] = $row.Bytes
            }
            if ($StopAt -eq "after-page-$pages") { throw 'interrupted' }
            & $AfterPage $pages
            $next = $page.Next
        }
        [decimal]$sum = 0
        foreach ($value in $values.Values) { $sum += $value }
        if ($sum -gt [long]::MaxValue) { throw 'sum-overflow' }
        $signature = ($values.Keys | Sort-Object -CaseSensitive | ForEach-Object { "$_=$($values[$_])" }) -join "`n"
        return @{ Status = 'enumeration-exhausted'; Bytes = [long]$sum; Objects = $values.Count; Pages = $pages; Rows = $rowCount; Signature = $signature }
    } catch {
        return @{ Status = 'incomplete'; Bytes = $null; Objects = $null; Pages = $pages; Rows = $rowCount; Reason = $_.Exception.Message }
    }
}

# Adds an assertion with the observed result, failing the run on any false expectation.
function Assert-Case([string]$Name, [bool]$Condition, $Observed) {
    $results.Add(@{ Name = $Name; Passed = $Condition; Observed = $Observed })
    if (-not $Condition) { throw "FAILED: $Name" }
    Write-Output "PASS: $Name"
}

# Only a validated, complete file is published. A fresh reader ignores the staging file after interruption.
function Publish-Capture($Capture, [string]$Destination, [string]$StopAt = '') {
    if ($Capture.Status -ne 'enumeration-exhausted') { return }
    if ($StopAt -eq 'before-write') { return }
    $Capture | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$Destination.partial"
    if ($StopAt -eq 'before-publish') { return }
    [IO.File]::Move("$Destination.partial", $Destination)
    # Returning here models loss of the caller response after the complete file exists.
}

$page1 = Join-Path $runRoot 'page1.json'
$page2 = Join-Path $runRoot 'page2.json'
Write-Page $page1 $rows[0..2] $page2
Write-Page $page2 $rows[3..5] $null
$known = Read-Capture $page1
Assert-Case 'known-bytes-and-duplicate-identities' ($known.Bytes -eq 60 -and $known.Objects -eq 4) $known
$repeat = Read-Capture $page1
Assert-Case 'matching-repeat-is-observational-only' ($known.Signature -ceq $repeat.Signature) $repeat
Write-Page $page1 @() $null
$zero = Read-Capture $page1
Assert-Case 'known-zero-exhausted-empty-source' ($zero.Status -eq 'enumeration-exhausted' -and $zero.Bytes -eq 0) $zero
Write-Page $page1 $rows[0..2] $page2
foreach ($stop in @('before-page-0', 'after-page-1', 'before-page-1', 'after-page-2')) {
    $failed = Read-Capture $page1 -StopAt $stop
    $fresh = Read-Capture $page1
    Assert-Case "interruption-$stop-and-fresh-retry" ($failed.Status -eq 'incomplete' -and $null -eq $failed.Bytes -and $fresh.Bytes -eq 60) @{ Failed = $failed; Retry = $fresh }
}
$bounded = Read-Capture $page1 -MaxPages 1
Assert-Case 'page-bound' ($bounded.Status -eq 'incomplete' -and $null -eq $bounded.Bytes) $bounded
$bounded = Read-Capture $page1 -MaxRows 2
Assert-Case 'row-bound' ($bounded.Status -eq 'incomplete' -and $null -eq $bounded.Bytes) $bounded
Write-Page $page1 $rows (Join-Path $runRoot 'absent.json')
$missing = Read-Capture $page1
Assert-Case 'missing-page-is-unknown' ($missing.Status -eq 'incomplete' -and $null -eq $missing.Bytes) $missing
foreach ($case in @(
    @{ Name = 'conflicting-size'; Row = @{ Scope = $scope; Key = $rows[0].Key; Bytes = 11 } },
    @{ Name = 'negative-size'; Row = @{ Scope = $scope; Key = 'negative'; Bytes = -1 } },
    @{ Name = 'malformed-size'; Row = @{ Scope = $scope; Key = 'malformed'; Bytes = '10' } },
    @{ Name = 'wrong-repository'; Row = @{ Scope = 'other'; Key = 'foreign'; Bytes = 10 } },
    @{ Name = 'overflow'; Row = @{ Scope = $scope; Key = 'large'; Bytes = [long]::MaxValue } }
)) {
    Write-Page $page1 @($rows[0], $case.Row) $null
    $invalid = Read-Capture $page1
    Assert-Case $case.Name ($invalid.Status -eq 'incomplete' -and $null -eq $invalid.Bytes) $invalid
}
# Real DTO fold preserved logical deletion. Removing the source page's rows models later physical source removal.
Write-Page $page1 @() $null
$removed = Read-Capture $page1
Assert-Case 'physical-source-removal-changes-diagnostic-only' ($known.Bytes -eq 60 -and $removed.Bytes -eq 0) @{ Before = $known.Bytes; After = $removed.Bytes; BlobPresence = 'unobserved' }
# Mutation after one page is read can combine values that never existed together: before=(10,20), after=(30,40).
$oldA = @{ Scope = $scope; Key = 'a'; Bytes = 10 }
$oldB = @{ Scope = $scope; Key = 'b'; Bytes = 20 }
$newA = @{ Scope = $scope; Key = 'a'; Bytes = 30 }
$newB = @{ Scope = $scope; Key = 'b'; Bytes = 40 }
Write-Page $page1 @($oldA) $page2
Write-Page $page2 @($oldB) $null
$mixed = Read-Capture $page1 -AfterPage {
    param($pageNumber)
    if ($pageNumber -eq 1) {
        Write-Page $page1 @($newA) $page2
        Write-Page $page2 @($newB) $null
    }
}
Assert-Case 'mixed-pages-cannot-establish-snapshot' ($mixed.Bytes -eq 50 -and $mixed.Bytes -notin @(30,70)) @{ Captured = $mixed; BeforeTotal = 30; AfterTotal = 70; AtomicSnapshot = $false }
Write-Page $page1 @($newA) $page2
$changed = Read-Capture $page1
Assert-Case 'second-scan-detects-observed-mutation' ($mixed.Signature -cne $changed.Signature) @{ First = $mixed.Bytes; Second = $changed.Bytes; EligibleAsTotal = $false }
foreach ($stop in @('before-write', 'before-publish', 'after-publish')) {
    $destination = Join-Path $runRoot "$stop.result.json"
    Publish-Capture $known $destination $stop
    # Restart from files only; discard the caller's result and reread the published path.
    $reopened = if (Test-Path -LiteralPath $destination) { Get-Content -LiteralPath $destination -Raw | ConvertFrom-Json } else { $null }
    $expectedPublished = $stop -eq 'after-publish'
    Assert-Case "capture-$stop-restart" (($null -ne $reopened) -eq $expectedPublished) @{ Published = ($null -ne $reopened); Partial = (Test-Path -LiteralPath "$destination.partial") }
    if (-not $expectedPublished) {
        $retryPath = Join-Path $runRoot "$stop.retry.json"
        Write-Page $page1 $rows $null
        Publish-Capture (Read-Capture $page1) $retryPath
        $retry = Get-Content -LiteralPath $retryPath -Raw | ConvertFrom-Json
        Assert-Case "capture-$stop-fresh-retry" ($retry.Bytes -eq 60) $retry
    }
}
@{ Verdict = 'simplified'; SourceGitBlob = $sourceSha; Cases = $results.ToArray(); Count = $results.Count;
    Platform = @{ Cosmos = 'not executed'; AzureBlob = 'not executed'; LocalFiles = 'executed'; GraceDtoSerializer = 'executed' };
    Limit = 'Enumeration exhaustion and repeat agreement do not establish an atomic repository snapshot.' } |
    ConvertTo-Json -Depth 20 | Set-Content -LiteralPath "$experimentRoot/results.json"
Write-Output "PASS: $($results.Count) capture assertions; repository total and billing remain unsupported."
